import os
import torch


class Config:
    # ==========================================
    # Path Configuration
    # ==========================================
    # Root directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata Paths (Generated by the provided script)
    # These files define the fixed Train/Val/Test splits
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Working Directory & Caching
    # All intermediate files and cache will be stored here
    WORKING_DIR = "./working/idea_11"
    CACHE_DIR = WORKING_DIR

    # Model and Submission Output
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = "./submission/submission.csv"

    # Ensure necessary directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(os.path.dirname(SUBMISSION_PATH), exist_ok=True)

    # ==========================================
    # Data Processing Configuration
    # ==========================================
    # Independent-Instance 2.5D Volumetric Ensemble (I2VE)

    # Input Specification
    IMAGE_SIZE = 224
    IN_CHANNELS = 3

    # Modality Selection
    # We stack these 3 modalities into the RGB channels of the backbone
    # Channel 1: FLAIR, Channel 2: T1wCE, Channel 3: T2w
    SELECTED_MODALITIES = ["FLAIR", "T1wCE", "T2w"]

    # ROI and Slice Extraction
    # We deterministically extract slices at these relative depths within the brain ROI
    SLICE_DEPTHS = [0.45, 0.50, 0.55]
    ROI_IGNORE_ZEROS = True  # Ignore zero-pixels when calculating bounding box

    # Normalization
    # Independent Channel Min-Max Scaling to [0, 1]
    # We avoid ImageNet mean/std to preserve MRI signal dynamics
    NORMALIZE_METHOD = "minmax"

    # Data Precision
    # Use float32 to maintain high dynamic range of medical images
    DATA_TYPE = "float32"

    # ==========================================
    # Model Architecture
    # ==========================================
    BACKBONE = "efficientnet_b0"
    PRETRAINED = True
    NUM_CLASSES = 1  # Binary Classification (MGMT_value)

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42

    # Batch Size and Epochs
    BATCH_SIZE = 32
    NUM_EPOCHS = 15

    # Optimizer (AdamW)
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2  # Strong regularization for small dataset

    # Early Stopping
    PATIENCE = 5

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 12  # Utilization of available vCPUs

    # ==========================================
    # Debugging / Development
    # ==========================================
    # If True, runs on a small subset of data to verify pipeline functionality
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 50
